<?php
session_start();require __DIR__.'/db.php';require __DIR__.'/helpers.php';$dates=$pdo->query('SELECT * FROM calendar_date ORDER BY calendar_date DESC LIMIT 365')->fetchAll();$status=$pdo->query('SELECT reservation_status_code code, COUNT(*) total FROM reservation GROUP BY reservation_status_code ORDER BY code')->fetchAll();$ticket=$pdo->query('SELECT ticket_type_code code, COUNT(*) total FROM reservation GROUP BY ticket_type_code ORDER BY code')->fetchAll();$classes=$pdo->query('SELECT travel_class_code code, COUNT(*) total FROM reservation GROUP BY travel_class_code ORDER BY code')->fetchAll();$pay=$pdo->query('SELECT payment_status_code code, COUNT(*) total FROM payment GROUP BY payment_status_code ORDER BY code')->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reference Records · HarborWing</title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="index.php">✈ HarborWing Air</a><span>Reservation Management</span></header><div class="layout"><aside><h3>Modules</h3><a class="navlink" href="index.php">Dashboard</a><a class="navlink" href="relations.php">Reservation Links</a><a class="navlink" href="reservation_details.php">Reservation Details</a><a class="navlink active" href="reference.php">Calendar / Reference</a></aside><main><p class="eyebrow">READ-ONLY REFERENCE</p><h1>Calendar & Reference Records</h1><p class="muted">These values are derived from your existing database. External codes such as airline, aircraft type, ticket type, and status are not separate lookup tables in the supplied schema.</p><section class="panel"><h2>Reservation status codes</h2><?php renderRef($status);?></section><section class="panel"><h2>Ticket type codes</h2><?php renderRef($ticket);?></section><section class="panel"><h2>Travel class codes</h2><?php renderRef($classes);?></section><section class="panel"><h2>Payment status codes</h2><?php renderRef($pay);?></section><section class="panel"><h2>Calendar dates (latest 365)</h2><div class="tablewrap"><table><thead><tr><th>Date</th><th>Day of month</th><th>Business day</th></tr></thead><tbody><?php foreach($dates as $d):?><tr><td><?=e($d['calendar_date'])?></td><td><?=e($d['day_of_month'])?></td><td><?=$d['is_business_day']?'Yes':'No'?></td></tr><?php endforeach;if(!$dates):?><tr><td colspan="3">No calendar records. Run the existing seed script for the calendar dates if your project instructions require it.</td></tr><?php endif;?></tbody></table></div></section></main></div><?php function renderRef($rows){echo '<div class="tablewrap"><table><thead><tr><th>Code</th><th>Records</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['code']).'</td><td>'.e($r['total']).'</td></tr>';if(!$rows)echo '<tr><td colspan="2">No values yet.</td></tr>';echo '</tbody></table></div>';}?></body></html>
